package com.bankpli.javabank.swift;import com.bankpli.javabank.audit.AuditService;import com.bankpli.javabank.shared.BusinessException;import java.math.BigDecimal;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;
@Service public class SwiftPaymentService {private final BicValidator validator;private final AuditService audit;public SwiftPaymentService(BicValidator v,AuditService a){validator=v;audit=a;}public record Payment(String messageType,String senderBic,String receiverBic,BigDecimal amount,String currency,String beneficiary,String remittance){}public record Result(String status,String reference){}public Result process(Payment p){if(!Set.of("103","202").contains(p.messageType()))throw new BusinessException(HttpStatus.BAD_REQUEST,"Only MT103 and MT202 are supported");if(!validator.isValid(p.senderBic())||!validator.isValid(p.receiverBic()))throw new BusinessException(HttpStatus.BAD_REQUEST,"Invalid BIC");if(p.amount()==null||p.amount().signum()<=0)throw new BusinessException(HttpStatus.BAD_REQUEST,"Amount must be positive");String ref="SWIFT-"+java.util.UUID.randomUUID();audit.append("SWIFT_PAYMENT",ref+" "+p.senderBic()+" -> "+p.receiverBic()+" "+p.amount()+" "+p.currency());return new Result("QUEUED",ref);}private static final class Set{static java.util.Set<String>of(String...v){return java.util.Set.of(v);}}}
